                queue[back++] = v;
            }
        }

        for (int k = 1; k < log; k++) {
            for (int v = 1; v <= n; v++) {
                int mid = ancestor[k - 1][v];
                ancestor[k][v] = ancestor[k - 1][mid];
                minEdge[k][v] = Math.min(minEdge[k - 1][v], minEdge[k - 1][mid]);
            }
        }

        int c = fs.nextInt();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < c; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            int answer = Integer.MAX_VALUE;

            if (depth[u] < depth[v]) {
                int temp = u;
                u = v;
                v = temp;
            }

            int difference = depth[u] - depth[v];
            for (int k = log - 1; k >= 0; k--) {
                if ((difference & (1 << k)) != 0) {
                    answer = Math.min(answer, minEdge[k][u]);
                    u = ancestor[k][u];
                }
            }

            if (u != v) {
                for (int k = log - 1; k >= 0; k--) {
                    if (ancestor[k][u] != ancestor[k][v]) {
                        answer = Math.min(answer, minEdge[k][u]);
                        answer = Math.min(answer, minEdge[k][v]);
                        u = ancestor[k][u];
                        v = ancestor[k][v];
                    }
                }
                answer = Math.min(answer, minEdge[0][u]);
                answer = Math.min(answer, minEdge[0][v]);
            }

            output.append(answer).append('\n');
        }

        System.out.print(output);
    }
